import React, { Component } from 'react';
import { Card, Table, Icon, Button, Spin, Alert, Input, Dropdown, Menu, Modal, message } from 'antd';
import { getInstance } from 'd2/lib/d2';
import PropTypes from 'prop-types';

const { Search } = Input;

class ThematicAreaList extends Component {
    constructor(props) {
        super(props);
        this.state = {
            organisationUnits: [], // Level 2 - Thematic Areas
            programs: {}, // Level 3 - Programs by thematic area
            projects: {}, // Projects by program
            loading: false,
            programsLoading: {}, // Loading state for programs
            projectsLoading: {}, // Loading state for projects
            error: null,
            expandedRowKeys: [],
            programExpandedRowKeys: {}, // Track expanded programs for each thematic area
            searchValue: '',
            filteredOrganisationUnits: [],
            allProgramsLoaded: false,
            allProjectsLoaded: false,
            deletingProjectId: null, // Track which project is being deleted
            deletingThematicAreaId: null // Track which thematic area is being deleted
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        this.fetchThematicAreas();
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchThematicAreas = async () => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('organisationUnits', {
                level: 2,
                paging: false
            });

            if (this._isMounted) {
                this.setState({
                    organisationUnits: data.organisationUnits || [],
                    filteredOrganisationUnits: data.organisationUnits || [],
                    loading: false
                });
            }
        } catch (error) {
            console.error('Error fetching thematic areas:', error);
            if (this._isMounted) {
                this.setState({
                    error: 'Failed to fetch thematic areas. Please try again.',
                    loading: false
                });
            }
        }
    };

    // Fetch programs (level 3) for a thematic area (level 2)
    fetchProgramsInThematicArea = async (thematicAreaId) => {
        if (!this._isMounted) return;

        this.setState(prevState => ({
            programsLoading: {
                ...prevState.programsLoading,
                [thematicAreaId]: true
            }
        }));

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('organisationUnits', {
                filter: `parent.id:eq:${thematicAreaId}`,
                level: 3,
                paging: false
            });

            if (this._isMounted) {
                this.setState(prevState => ({
                    programs: {
                        ...prevState.programs,
                        [thematicAreaId]: data.organisationUnits || []
                    },
                    programsLoading: {
                        ...prevState.programsLoading,
                        [thematicAreaId]: false
                    }
                }));
            }
        } catch (error) {
            console.error('Error fetching programs:', error);
            if (this._isMounted) {
                this.setState(prevState => ({
                    programs: {
                        ...prevState.programs,
                        [thematicAreaId]: []
                    },
                    programsLoading: {
                        ...prevState.programsLoading,
                        [thematicAreaId]: false
                    }
                }));
            }
        }
    };

    // Fetch projects for a specific program
    fetchProjectsInProgram = async (programId) => {
        if (!this._isMounted) return;

        this.setState(prevState => ({
            projectsLoading: {
                ...prevState.projectsLoading,
                [programId]: true
            }
        }));

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('programs', {
                filter: `organisationUnits.id:eq:${programId}`,
                fields: 'id,displayName,code,programType',
                paging: false
            });

            if (this._isMounted) {
                this.setState(prevState => ({
                    projects: {
                        ...prevState.projects,
                        [programId]: data.programs || []
                    },
                    projectsLoading: {
                        ...prevState.projectsLoading,
                        [programId]: false
                    }
                }));
            }
        } catch (error) {
            console.error('Error fetching projects:', error);
            if (this._isMounted) {
                this.setState(prevState => ({
                    projects: {
                        ...prevState.projects,
                        [programId]: []
                    },
                    projectsLoading: {
                        ...prevState.projectsLoading,
                        [programId]: false
                    }
                }));
            }
        }
    };

    // Fetch all data for comprehensive search
    fetchAllData = async () => {
        if (this.state.allProjectsLoaded && this.state.allProgramsLoaded) return;

        const { organisationUnits } = this.state;

        try {
            // First, fetch all programs for all thematic areas
            const d2 = await getInstance();
            const api = d2.Api.getApi();

            const programPromises = organisationUnits.map(async (unit) => {
                try {
                    const data = await api.get('organisationUnits', {
                        filter: `parent.id:eq:${unit.id}`,
                        level: 3,
                        paging: false
                    });
                    return { thematicAreaId: unit.id, programs: data.organisationUnits || [] };
                } catch (error) {
                    console.error(`Error fetching programs for ${unit.id}:`, error);
                    return { thematicAreaId: unit.id, programs: [] };
                }
            });

            const programResults = await Promise.all(programPromises);
            const allPrograms = {};
            const allProgramsList = [];

            programResults.forEach(result => {
                allPrograms[result.thematicAreaId] = result.programs;
                allProgramsList.push(...result.programs);
            });

            if (this._isMounted) {
                this.setState({
                    programs: allPrograms,
                    allProgramsLoaded: true
                });
            }

            // Then, fetch all projects for all programs
            const projectPromises = allProgramsList.map(async (program) => {
                try {
                    const data = await api.get('programs', {
                        filter: `organisationUnits.id:eq:${program.id}`,
                        fields: 'id,displayName,code,programType',
                        paging: false
                    });
                    return { programId: program.id, projects: data.programs || [] };
                } catch (error) {
                    console.error(`Error fetching projects for ${program.id}:`, error);
                    return { programId: program.id, projects: [] };
                }
            });

            const projectResults = await Promise.all(projectPromises);
            const allProjects = {};

            projectResults.forEach(result => {
                allProjects[result.programId] = result.projects;
            });

            if (this._isMounted) {
                this.setState({
                    projects: allProjects,
                    allProjectsLoaded: true
                });
            }
        } catch (error) {
            console.error('Error fetching all data:', error);
        }
    };

    handleThematicAreaExpand = (expanded, record) => {
        if (expanded && !this.state.programs[record.id]) {
            this.fetchProgramsInThematicArea(record.id);
        }
    };

    handleProgramExpand = (expanded, record, thematicAreaId) => {
        if (expanded && !this.state.projects[record.id]) {
            this.fetchProjectsInProgram(record.id);
        }

        // Update expanded program keys for this thematic area
        this.setState(prevState => ({
            programExpandedRowKeys: {
                ...prevState.programExpandedRowKeys,
                [thematicAreaId]: expanded
                    ? [...(prevState.programExpandedRowKeys[thematicAreaId] || []), record.id]
                    : (prevState.programExpandedRowKeys[thematicAreaId] || []).filter(key => key !== record.id)
            }
        }));
    };

    handleSearch = async (value) => {
        const { organisationUnits } = this.state;

        if (!value.trim()) {
            this.setState({
                searchValue: value,
                filteredOrganisationUnits: organisationUnits,
                expandedRowKeys: [],
                programExpandedRowKeys: {}
            });
            return;
        }

        // Ensure all data is loaded for comprehensive search
        if (!this.state.allProgramsLoaded || !this.state.allProjectsLoaded) {
            await this.fetchAllData();
        }

        const searchTerm = value.toLowerCase();
        const filteredUnits = [];
        const autoExpandKeys = [];
        const autoExpandPrograms = {};

        organisationUnits.forEach(unit => {
            // Check if thematic area matches
            const unitMatches = unit.displayName.toLowerCase().includes(searchTerm) ||
                unit.id.toLowerCase().includes(searchTerm) ||
                (unit.code && unit.code.toLowerCase().includes(searchTerm));

            // Check programs and projects
            const unitPrograms = this.state.programs[unit.id] || [];
            let hasMatchingProgram = false;
            let matchingProgramIds = [];

            unitPrograms.forEach(program => {
                const programMatches = program.displayName.toLowerCase().includes(searchTerm) ||
                    program.id.toLowerCase().includes(searchTerm) ||
                    (program.code && program.code.toLowerCase().includes(searchTerm));

                // Check projects in this program
                const programProjects = this.state.projects[program.id] || [];
                const projectMatches = programProjects.some(project =>
                    project.displayName.toLowerCase().includes(searchTerm) ||
                    project.id.toLowerCase().includes(searchTerm) ||
                    (project.code && project.code.toLowerCase().includes(searchTerm))
                );

                if (programMatches || projectMatches) {
                    hasMatchingProgram = true;
                    matchingProgramIds.push(program.id);
                }
            });

            // Include the thematic area if it or its children match
            if (unitMatches || hasMatchingProgram) {
                filteredUnits.push(unit);

                // Auto-expand if children match
                if (hasMatchingProgram) {
                    autoExpandKeys.push(unit.id);
                    autoExpandPrograms[unit.id] = matchingProgramIds;
                }
            }
        });

        this.setState({
            searchValue: value,
            filteredOrganisationUnits: filteredUnits,
            expandedRowKeys: autoExpandKeys,
            programExpandedRowKeys: autoExpandPrograms
        });
    };

    handleProjectClick = (project, program) => {
        const redirectUrl = `/sims-web-maintenance/#/edit/programSection/program/${project.id}`;
        window.location.href = redirectUrl;
    };

    handleProjectView = (project, program) => {
        // Navigate based on project type
        let redirectUrl;

        if (project.programType === 'WITHOUT_REGISTRATION') {
            // For WITHOUT_REGISTRATION (Forms)projects, go to capture (Forms) app
            redirectUrl = `/sims-web-capture/#/?orgUnitId=${program.id}&programId=${project.id}`;
        } else if (project.programType === 'WITH_REGISTRATION') {
            // For WITH_REGISTRATION (Spreadsheet) projects, go to aggregate data entry (Spreadsheet) app
            redirectUrl = `/sims-web-aggregate-data-entry/#/?orgUnitId=${program.id}`;
        }

        window.location.href = redirectUrl;
    };

    handleProjectDelete = (project, program) => {
        Modal.confirm({
            title: 'Delete Project',
            content: (
                <div>
                    <p>Are you sure you want to delete the project <strong>"{project.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteProject(project.id, program.id);
            },
        });
    };

    handleThematicAreaDelete = (thematicArea) => {
        Modal.confirm({
            title: 'Delete Thematic Area',
            content: (
                <div>
                    <p>Are you sure you want to delete the thematic area <strong>"{thematicArea.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action will also delete all associated programs and projects. This cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteThematicArea(thematicArea.id);
            },
        });
    };

    deleteProject = async (projectId, programId) => {
        this.setState({ deletingProjectId: projectId });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            await api.delete(`programs/${projectId}`);

            // Remove the deleted project from state
            const updatedProjects = { ...this.state.projects };
            if (updatedProjects[programId]) {
                updatedProjects[programId] = updatedProjects[programId].filter(project => project.id !== projectId);
            }

            this.setState({
                projects: updatedProjects,
                deletingProjectId: null
            });

            message.success('Project deleted successfully');
        } catch (error) {
            console.error('Error deleting project:', error);
            this.setState({ deletingProjectId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the project: ${error.message}`,
            });
        }
    };

    deleteThematicArea = async (thematicAreaId) => {
        this.setState({ deletingThematicAreaId: thematicAreaId });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            await api.delete(`organisationUnits/${thematicAreaId}`);

            // Remove the deleted thematic area from state
            const updatedOrganisationUnits = this.state.organisationUnits.filter(unit => unit.id !== thematicAreaId);
            const updatedFilteredUnits = this.state.filteredOrganisationUnits.filter(unit => unit.id !== thematicAreaId);

            // Clean up related data
            const updatedPrograms = { ...this.state.programs };
            const updatedProjects = { ...this.state.projects };
            const updatedProgramsLoading = { ...this.state.programsLoading };
            const updatedProjectsLoading = { ...this.state.projectsLoading };
            const updatedProgramExpandedRowKeys = { ...this.state.programExpandedRowKeys };

            delete updatedPrograms[thematicAreaId];
            delete updatedProgramsLoading[thematicAreaId];
            delete updatedProgramExpandedRowKeys[thematicAreaId];

            // Remove projects data for all programs in this thematic area
            const programsInArea = this.state.programs[thematicAreaId] || [];
            programsInArea.forEach(program => {
                delete updatedProjects[program.id];
                delete updatedProjectsLoading[program.id];
            });

            this.setState({
                organisationUnits: updatedOrganisationUnits,
                filteredOrganisationUnits: updatedFilteredUnits,
                programs: updatedPrograms,
                projects: updatedProjects,
                programsLoading: updatedProgramsLoading,
                projectsLoading: updatedProjectsLoading,
                programExpandedRowKeys: updatedProgramExpandedRowKeys,
                deletingThematicAreaId: null,
                expandedRowKeys: this.state.expandedRowKeys.filter(key => key !== thematicAreaId)
            });

            message.success('Thematic area deleted successfully');
        } catch (error) {
            console.error('Error deleting thematic area:', error);
            this.setState({ deletingThematicAreaId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the thematic area: ${error.message}`,
            });
        }
    };

    handleCreateThematicArea = () => {
        // Navigate to create new thematic area (organization unit level 2)
        const redirectUrl = `/sims-web-maintenance/#/edit/organisationUnitSection/organisationUnit/add`;
        window.location.href = redirectUrl;
    };

    handleThematicAreaEdit = (thematicArea) => {
        // Navigate to edit thematic area (organization unit level 2)
        const redirectUrl = `/sims-web-maintenance/#/edit/organisationUnitSection/organisationUnit/${thematicArea.id}`;
        window.location.href = redirectUrl;
    };


    // Get more actions menu for projects
    getProjectActionsMenu = (project, program, thematicArea) => {
        const { deletingProjectId } = this.state;
        const isDeleting = deletingProjectId === project.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleProjectClick(project, program)}>
                    <Icon type="edit" style={{ marginRight: '8px' }} />
                    Edit Project Details
                </Menu.Item>
                <Menu.Item key="view" onClick={() => this.handleProjectView(project, program, thematicArea)}>
                    <Icon type="eye" style={{ marginRight: '8px' }} />
                    View / Add Data
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleProjectDelete(project, program)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Project'}
                </Menu.Item>
            </Menu>
        );
    };

    // Get actions menu for thematic areas
    getThematicAreaActionsMenu = (thematicArea) => {
        const { deletingThematicAreaId } = this.state;
        const isDeleting = deletingThematicAreaId === thematicArea.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleThematicAreaEdit(thematicArea)}>
                    <Icon type="edit" style={{ marginRight: '8px' }} />
                    Edit Thematic Area
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleThematicAreaDelete(thematicArea)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Thematic Area'}
                </Menu.Item>
            </Menu>
        );
    };

    // Render projects table for a program
    renderProjectsTable = (program, thematicAreaId) => {
        const { projects, projectsLoading, searchValue, organisationUnits } = this.state;
        const programProjects = projects[program.id] || [];
        const isLoading = projectsLoading[program.id];
        const thematicArea = organisationUnits.find(unit => unit.id === thematicAreaId);

        if (isLoading) {
            return (
                <div style={{ textAlign: 'center', padding: '16px' }}>
                    <Spin size="small" />
                    <div style={{ marginTop: '8px', color: '#666' }}>Loading projects...</div>
                </div>
            );
        }

        if (programProjects.length === 0) {
            return (
                <div style={{
                    padding: '16px',
                    textAlign: 'center',
                    color: '#999',
                    fontStyle: 'italic'
                }}>
                    <Icon type="warning" style={{ marginRight: '8px' }} />
                    No projects found in this program.
                </div>
            );
        }

        // Filter projects based on search
        let displayProjects = programProjects;
        if (searchValue && searchValue.trim()) {
            const searchTerm = searchValue.toLowerCase();
            displayProjects = programProjects.filter(project =>
                project.displayName.toLowerCase().includes(searchTerm) ||
                project.id.toLowerCase().includes(searchTerm) ||
                (project.code && project.code.toLowerCase().includes(searchTerm))
            );
        }

        const projectColumns = [
            {
                title: 'Project Name',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, project) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="file-text" style={{ color: '#52c41a', marginRight: '8px' }} />
                            <span
                                style={{ fontWeight: '500' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                render: (text, project) => (
                    <Dropdown
                        overlay={this.getProjectActionsMenu(project, program, thematicArea)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        return (
            <Table
                columns={projectColumns}
                dataSource={displayProjects}
                pagination={false}
                size="small"
                rowKey="id"
                bordered={false}
                style={{ margin: '0 16px 16px 16px' }}
            />
        );
    };

    // Render programs table for a thematic area
    expandedRowRender = (thematicArea) => {
        const { programs, programsLoading, searchValue, programExpandedRowKeys } = this.state;
        const areaPrograms = programs[thematicArea.id] || [];
        const isLoading = programsLoading[thematicArea.id];

        if (isLoading) {
            return (
                <div style={{ textAlign: 'center', padding: '24px' }}>
                    <Spin size="small" />
                    <div style={{ marginTop: '8px', color: '#666' }}>Loading programs...</div>
                </div>
            );
        }

        if (areaPrograms.length === 0) {
            return (
                <div style={{
                    padding: '16px',
                    textAlign: 'center',
                    color: '#999',
                    fontStyle: 'italic'
                }}>
                    <Icon type="warning" style={{ marginRight: '8px' }} />
                    No programs found in this thematic area.
                </div>
            );
        }

        // Filter programs based on search
        let displayPrograms = areaPrograms;
        if (searchValue && searchValue.trim()) {
            const searchTerm = searchValue.toLowerCase();
            displayPrograms = areaPrograms.filter(program => {
                const programMatches = program.displayName.toLowerCase().includes(searchTerm) ||
                    program.id.toLowerCase().includes(searchTerm) ||
                    (program.code && program.code.toLowerCase().includes(searchTerm));

                // Also check if any projects in this program match
                const programProjects = this.state.projects[program.id] || [];
                const projectMatches = programProjects.some(project =>
                    project.displayName.toLowerCase().includes(searchTerm) ||
                    project.id.toLowerCase().includes(searchTerm) ||
                    (project.code && project.code.toLowerCase().includes(searchTerm))
                );

                return programMatches || projectMatches;
            });
        }

        const programColumns = [
            {
                title: 'Program Name',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, program) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="project" style={{ color: '#fa8c16', marginRight: '8px', fontSize: '14px' }} />
                            <span
                                style={{ fontWeight: '500', fontSize: '14px' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
        ];

        return (
            <div style={{ margin: '0 24px 24px 24px' }}>
                <Table
                    columns={programColumns}
                    dataSource={displayPrograms}
                    pagination={false}
                    size="small"
                    rowKey="id"
                    bordered={false}
                    expandedRowRender={(program) => this.renderProjectsTable(program, thematicArea.id)}
                    onExpand={(expanded, program) => this.handleProgramExpand(expanded, program, thematicArea.id)}
                    expandedRowKeys={programExpandedRowKeys[thematicArea.id] || []}
                />
            </div>
        );
    };

    render() {
        const { organisationUnits, loading, error, searchValue, filteredOrganisationUnits, expandedRowKeys } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '1200px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading thematic areas...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={this.fetchThematicAreas}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        const columns = [
            {
                title: 'Thematic Area',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, record) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="folder" style={{ color: '#1890ff', marginRight: '8px', fontSize: '16px' }} />
                            <span
                                style={{ fontWeight: '500', fontSize: '16px' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                render: (text, thematicArea) => (
                    <Dropdown
                        overlay={this.getThematicAreaActionsMenu(thematicArea)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        const dataSource = searchValue ? filteredOrganisationUnits : organisationUnits;

        return (
            <div>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Thematic Areas
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Navigate through Thematic Areas → Programs → Projects using the expand icons
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Table Content */}
                    <div style={{ padding: '0 24px 24px 24px' }}>
                        {organisationUnits.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '60px 0', color: '#999' }}>
                                <Icon type="folder-open" style={{ fontSize: '64px', color: '#d9d9d9', marginBottom: '16px' }} />
                                <div style={{ fontSize: '16px' }}>No thematic areas found</div>
                            </div>
                        ) : (
                            <div>
                                <Search
                                    placeholder="Search across thematic areas, programs, and projects by name, code or ID"
                                    value={searchValue}
                                    onChange={(e) => this.handleSearch(e.target.value)}
                                    style={{ width: 500, marginBottom: 16 }}
                                />
                                {searchValue && (
                                    <div style={{ marginBottom: 16, color: '#666', fontSize: '14px' }}>
                                        <Icon type="search" style={{ marginRight: '4px' }} />
                                        Found {dataSource.length} thematic area(s) for "{searchValue}"
                                        {dataSource.length > 0 && expandedRowKeys.length > 0 && (
                                            <span style={{ marginLeft: '8px', color: '#1890ff' }}>
                                                (Matching items are automatically expanded)
                                            </span>
                                        )}
                                    </div>
                                )}
                                <Table
                                    columns={columns}
                                    dataSource={dataSource}
                                    rowKey="id"
                                    expandedRowRender={this.expandedRowRender}
                                    onExpand={this.handleThematicAreaExpand}
                                    expandedRowKeys={expandedRowKeys}
                                    onExpandedRowsChange={(keys) => this.setState({ expandedRowKeys: keys })}
                                    pagination={{
                                        pageSize: 10,
                                        showSizeChanger: true,
                                        showQuickJumper: true,
                                        showTotal: (total, range) =>
                                            `${range[0]}-${range[1]} of ${total} ${searchValue ? 'filtered' : ''} thematic areas`,
                                    }}
                                    size="middle"
                                />
                            </div>
                        )}
                    </div>
                </Card>

                {/* Floating Add Thematic Area Button */}
                <div style={{
                    position: 'fixed',
                    bottom: '24px',
                    right: '24px',
                    zIndex: 1000
                }}>
                    <Button
                        type="primary"
                        size="large"
                        shape="circle"
                        icon="plus"
                        onClick={this.handleCreateThematicArea}
                        style={{
                            width: '56px',
                            height: '56px',
                            fontSize: '20px',
                            boxShadow: '0 4px 12px rgba(24, 144, 255, 0.3)',
                            border: 'none'
                        }}
                        title="Add New Thematic Area"
                    />
                </div>
            </div>
        );
    }
}

ThematicAreaList.contextTypes = {
    d2: PropTypes.object
};

export default ThematicAreaList;



